# Probe Yealink W70B API
$base='http://192.168.20.57'
$paths=@('/','/api','/api/','/servlet?p=login&q=loginForm','/cgi-bin/ConfigManApp.com','/api/auth','/api/v1','/api/system','/api/status')
foreach($p in $paths){
  try{
    $r=Invoke-WebRequest -Uri ($base+$p) -UseBasicParsing -TimeoutSec 8 -MaximumRedirection 0 -ErrorAction Stop
    "OK $p $($r.StatusCode) $($r.Headers['Content-Type']) len=$($r.RawContentLength)"
    if($r.Content.Length -lt 500){ $r.Content }
  } catch {
    $resp=$_.Exception.Response
    if($resp){ "HTTP $p $([int]$resp.StatusCode) $($resp.Headers['Location'])" } else { "ERR $p $($_.Exception.Message)" }
  }
}

# Try HTTPS API + basic auth common Yealink
$ErrorActionPreference='Continue'
$base='https://192.168.20.57'
# ignore cert
add-type @"
using System.Net; using System.Security.Cryptography.X509Certificates;
public class T:ICertificatePolicy{public bool CheckValidationResult(ServicePoint s,X509Certificate c,WebRequest r,int p){return true;}}
"@
[System.Net.ServicePointManager]::CertificatePolicy = New-Object T
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

$creds=@(@{u='admin';p='admin'},@{u='admin';p=''},@{u='admin';p='Admin'})
foreach($c in $creds){
  $pair=[Convert]::ToBase64String([Text.Encoding]::ASCII.GetBytes("$($c.u):$($c.p)"))
  $h=@{Authorization="Basic $pair"}
  foreach($p in @('/api','/api/','/api/system/status','/api/handset/list','/cgi-bin/ConfigManApp.com?key=Status&type=status')){
    try{
      $r=Invoke-WebRequest -Uri ($base+$p) -Headers $h -UseBasicParsing -TimeoutSec 10
      "OK $($c.u) $p $($r.StatusCode) len=$($r.RawContentLength)"
      $r.Content.Substring(0,[Math]::Min(300,$r.Content.Length))
      break
    } catch {
      $code=$_.Exception.Response.StatusCode.value__
      "FAIL $($c.u) $p code=$code msg=$($_.Exception.Message)"
    }
  }
}

# HTTP with basic too
foreach($c in $creds){
  $pair=[Convert]::ToBase64String([Text.Encoding]::ASCII.GetBytes("$($c.u):$($c.p)"))
  try{
    $r=Invoke-WebRequest -Uri 'http://192.168.20.57/api/' -Headers @{Authorization="Basic $pair"} -UseBasicParsing -TimeoutSec 8
    "HTTP OK $($c.u) $($r.StatusCode) $($r.Content.Substring(0,[Math]::Min(200,$r.Content.Length)))"
  } catch { "HTTP FAIL $($c.u) $($_.Exception.Message)" }
}

# Discover Yealink W70B login endpoints from SPA assets
$ErrorActionPreference='Continue'
try {
  $r=Invoke-WebRequest -Uri 'https://192.168.20.57/api/' -SkipCertificateCheck -UseBasicParsing -TimeoutSec 10
} catch {
  # PS5 fallback
  add-type @"
using System.Net;using System.Security.Cryptography.X509Certificates;
public class T2:ICertificatePolicy{public bool CheckValidationResult(ServicePoint s,X509Certificate c,WebRequest r,int p){return true;}}
"@ -ErrorAction SilentlyContinue
  [System.Net.ServicePointManager]::CertificatePolicy = New-Object T2
  $r=Invoke-WebRequest -Uri 'https://192.168.20.57/api/' -UseBasicParsing -TimeoutSec 10
}
# get js bundles
$js = [regex]::Matches($r.Content,'src="([^"]+\.js)"') | ForEach-Object { $_.Groups[1].Value }
$js | ForEach-Object { $_ }
# fetch first few and search login paths
foreach($j in ($js | Select-Object -First 5)){
  $u = if($j.StartsWith('http')){$j}elseif($j.StartsWith('/')){"https://192.168.20.57$j"}else{"https://192.168.20.57/api/$j"}
  try{
    $c=(Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 15 -SkipCertificateCheck).Content
  } catch {
    try{$c=(Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 15).Content}catch{continue}
  }
  $hits=[regex]::Matches($c,'(/[a-zA-Z0-9_/\-\.]*login[a-zA-Z0-9_/\-\.]*)|(/api/[a-zA-Z0-9_/\-\.]{3,40})|rsid|RAccount|handset')
  "==== $u hits=$($hits.Count) ===="
  $hits | Select-Object -First 40 | ForEach-Object { $_.Value }
}

