# Sustained jitter sample to Krylovа OVPN peer and base
$targets = @('10.220.220.252','192.168.20.57','192.168.20.1')
foreach($ip in $targets){
  $times = @()
  1..30 | ForEach-Object {
    $t = (Test-Connection $ip -Count 1 -ErrorAction SilentlyContinue).ResponseTime
    if($null -ne $t){ $times += [int]$t }
  }
  if($times.Count){
    $sorted = $times | Sort-Object
    $p50 = $sorted[[int](($sorted.Count-1)*0.5)]
    $p95 = $sorted[[int](($sorted.Count-1)*0.95)]
    $spikes = ($times | Where-Object { $_ -gt 100 }).Count
    "$ip n=$($times.Count) min=$($sorted[0]) p50=$p50 avg=$([int](($times|Measure-Object -Average).Average)) p95=$p95 max=$($sorted[-1]) spikes>100ms=$spikes"
